/* Local demo files live in IndexedDB; URLs are not persisted. */
(function(root){
'use strict';let dbPromise;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!root.indexedDB)return reject(Error('В этом браузере недоступно хранение файлов'));const r=indexedDB.open('forma-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Не удалось открыть хранилище файлов'));r.onblocked=()=>reject(Error('Закройте другие вкладки с приложением и повторите'))});return dbPromise;}
async function operation(mode,action){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('files',mode);let result;const req=action(tx.objectStore('files'));if(req)req.onsuccess=()=>{result=req.result};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Не удалось сохранить файл. Проверьте свободное место'));tx.onabort=()=>reject(Error('Сохранение файла прервано'));});}
async function validate(file,imageOnly=false){if(!file||!file.size)throw Error('Выберите непустой файл');if(file.size>8*1024*1024)throw Error('Файл больше 8 МБ. Выберите файл поменьше');const a=new Uint8Array(await file.slice(0,16).arrayBuffer());let type='';if(a[0]===255&&a[1]===216&&a[2]===255)type='image/jpeg';if(a[0]===137&&a[1]===80&&a[2]===78&&a[3]===71)type='image/png';if(String.fromCharCode(...a.slice(0,4))==='RIFF'&&String.fromCharCode(...a.slice(8,12))==='WEBP')type='image/webp';if(String.fromCharCode(...a.slice(0,5))==='%PDF-')type='application/pdf';if(!type||imageOnly&&type==='application/pdf')throw Error(imageOnly?'Выберите фотографию JPG, PNG или WebP':'Поддерживаются PDF, JPG, PNG и WebP');if(imageOnly){try{const bitmap=await createImageBitmap(file);if(bitmap.width<100||bitmap.height<100){bitmap.close();throw Error('Фотография должна быть не меньше 100 × 100 пикселей')}bitmap.close();}catch(e){throw Error(e.message.includes('100')?e.message:'Фотографию не удалось прочитать')}}return type;}
async function put(file,imageOnly=false){const type=await validate(file,imageOnly);const id='file-'+crypto.randomUUID();const blob=new Blob([file],{type});await operation('readwrite',s=>s.put({id,blob,name:file.name,type,size:file.size,createdAt:Date.now()}));return {id,name:file.name,type,size:file.size};}
root.FormaFiles={put,get:id=>operation('readonly',s=>s.get(id)),remove:id=>operation('readwrite',s=>s.delete(id)),all:()=>operation('readonly',s=>s.getAll())};
})(window);
